def get_nested_value(data, path):
    if not path:
        return data if isinstance(data, dict) else None

    # Normalize path to lowercase for case-insensitive matching
    path_lower = path.lower()
    keys = path_lower.split('.')

    current = data
    for key in keys:
        if not isinstance(current, dict):
            return None

        # Find a key in current that matches the lowercase target (case-insensitive)
        found_key = None
        for k in current:
            if k.lower() == key:
                found_key = k
                break

        if found_key is None:
            return None

        current = current[found_key]

    return current
