def generate_combinations(elements, k):
    # Base cases
    if k == 0:
        return [()]
    if k > len(elements):
        return []

    result = []

    def backtrack(start, current):
        if len(current) == k:
            result.append(tuple(current))
            return

        for i in range(start, len(elements)):
            current.append(elements[i])
            backtrack(i + 1, current)
            current.pop()

    backtrack(0, [])
    return result
```

