def reverseWords(s):
    words = []
    current_word = []
    current_whitespace = []

    for char in s:
        if char.isspace():
            if current_word:
                words.append("".join(current_word))
                current_word = []
            current_whitespace.append(char)
        else:
            current_word.append(char)

    if current_word:
        words.append("".join(current_word))

    # Reverse the list of words
    words.reverse()

    # Reconstruct the string preserving original whitespace blocks
    result = []
    word_index = 0

    for ws_block in current_whitespace if current_whitespace else []:
        # This approach is flawed because we lost the mapping of whitespace blocks to positions.
        # Let's redo with a cleaner two-pass approach.
        pass

    # Correct approach:
    # Split into tokens: words and whitespace runs, then reverse words but keep whitespace runs in place.
    tokens = []
    i = 0
    n = len(s)
    while i < n:
        if s[i].isspace():
            start = i
            while i < n and s[i].isspace():
                i += 1
            tokens.append(("ws", s[start:i]))
        else:
            start = i
            while i < n and not s[i].isspace():
                i += 1
            tokens.append(("word", s[start:i]))

    # Separate words and whitespace runs
    words_list = []
    ws_runs = []
    ws_run_index = 0

    for typ, content in tokens:
        if typ == "word":
            words_list.append(content)
        else:
            ws_runs.append((ws_run_index, content))
            ws_run_index += 1

    # Reverse the words list
    words_list.reverse()

    # Rebuild tokens with reversed words but original whitespace runs
    new_tokens = []
    word_idx = 0
    for typ, content in tokens:
        if typ == "word":
            new_tokens.append(("word", words_list[word_idx]))
            word_idx += 1
        else:
            new_tokens.append(("ws", content))

    # Join back
    result = []
    for typ, content in new_tokens:
        result.append(content)

    return "".join(result)

