def filter_waking_up_timestamps(timestamps, waking_up_keywords):
    import re

    def is_valid_timestamp(ts):
        ts = ts.strip()
        # Pattern for HH:MM:SS, HH:MM, or HH:MM AM/PM
        pattern = r'^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?$', r'^(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(AM|PM)?$'
        match = re.match(pattern, ts, re.IGNORECASE)
        if not match:
            return False
        hour, minute, second, period = match.groups()
        hour, minute = int(hour), int(minute)
        if second is not None:
            second = int(second)
        if period is not None:
            period = period.upper()
        if period == 'AM' and hour >= 12:
            return False
        if period == 'PM' and hour == 0:
            return False
        if minute < 0 or minute > 59:
            return False
        if second is not None and (second < 0 or second > 59):
            return False
        return True

    def contains_keyword(ts, keywords):
        ts_lower = ts.lower()
        for kw in keywords:
            if kw.lower() in ts_lower:
                return True
        return False

    result = []
    for ts in timestamps:
        if is_valid_timestamp(ts) and contains_keyword(ts, waking_up_keywords):
            result.append(ts)
    return result
```

