def generate_response(status_code):
    _cache = {}

    def _build_200():
        return "HTTP/1.1 200 OK\r\nServer: ExampleServer/1.1\r\nContent-Type: text/html\r\nConnection: close\r\n"

    def _build_error(code, title, message):
        body = f"<html><head><title>{title}</title></head><body><h1>{message}</h1></body></html>"
        return f"HTTP/1.1 {code} {title}\r\nServer: ExampleServer/1.1\r\nContent-Type: text/html\r\nConnection: close\r\n\r\n{body}"

    if status_code in _cache:
        return _cache[status_code]

    if status_code == 200:
        response = _build_200()
    elif status_code == 404:
        response = _build_error(404, "Not Found", "404 Not Found")
    elif status_code == 400:
        response = _build_error(400, "Bad Request", "400 Bad Request")
    elif status_code == 500:
        response = _build_error(500, "Internal Server Error", "500 Internal Server Error")
    else:
        raise NotImplementedError(f"Status code {status_code} is not implemented.")

    _cache[status_code] = response
    return response
```

