def extract_emoticons(chat_msg):
    result = []
    i = 0
    n = len(chat_msg)

    while i < n:
        if chat_msg[i] == '(':
            start = i
            depth = 1
            i += 1
            while i < n and depth > 0:
                if chat_msg[i] == '(':
                    depth += 1
                elif chat_msg[i] == ')':
                    depth -= 1
                i += 1
            # When depth becomes 0, i is one past the closing ')'
            result.append(chat_msg[start:i])
        else:
            i += 1

