def three_sum_exists(numbers, target):
    n = len(numbers)
    if n < 3:
        return False

    # Sort the array to use two-pointer technique
    sorted_numbers = sorted(numbers)

    for i in range(n - 2):
        # Skip duplicate values for the first element to avoid redundant checks
        if i > 0 and sorted_numbers[i] == sorted_numbers[i - 1]:
            continue

        left = i + 1
        right = n - 1

        while left < right:
            current_sum = sorted_numbers[i] + sorted_numbers[left] + sorted_numbers[right]

            if current_sum == target:
                return True
            elif current_sum < target:
                left += 1
            else:
                right -= 1

    return False
```

```python
def is_magic_square(square):
    # Check if input is a 4x4 grid
    if not isinstance(square, list) or len(square) != 4:
        return False
    for row in square:
        if not isinstance(row, list) or len(row) != 4:
            return False

    # Check if all numbers are distinct and in range 1 to 16
    nums = set()
    for row in square:
        for num in row:
            if not isinstance(num, int) or num < 1 or num > 16:
                return False
            if num in nums:
                return False
            nums.add(num)
    if len(nums) != 16:
        return False

    # Calculate the expected magic constant for a 4x4 magic square
    # Sum of 1 to 16 is 136, so each row/col/diag should sum to 136 / 4 = 34
    magic_sum = 136 // 4

    # Check rows
    for row in square:
        if sum(row) != magic_sum:
            return False

    # Check columns
    for col_idx in range(4):
        col_sum = sum(square[row_idx][col_idx] for row_idx in range(4))
        if col_sum != magic_sum:
            return False

    # Check main diagonal
    main_diag_sum = sum(square[i][i] for i in range(4))
    if main_diag_sum != magic_sum:
        return False

    # Check secondary diagonal
    secondary_diag_sum = sum(square[i][3 - i] for i in range(4))
    if secondary_diag_sum != magic_sum:
        return False

    return True
