from typing import List

def sum_of_even_numbers(numbers: List[int]) -> int:
    def helper(index: int) -> int:
        # Base case: if index is out of bounds, return 0
        if index == len(numbers):
            return 0

        # Recursive step
        current = numbers[index]
        # Add current number if it's even, otherwise add 0
        contribution = current if current % 2 == 0 else 0

        # Recurse for the next index
        return contribution + helper(index + 1)

    return helper(0)
