def main_find_smallest_prime_factor(n):
    def smallest_prime_factor(x):
        if x % 2 == 0:
            return 2
        i = 3
        while i * i <= x:
            if x % i == 0:
                return i
            i += 2
        return x

    # Compute product of all primes up to and including n
    primes_up_to_n = []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, n + 1):
        if is_prime[p]:
            primes_up_to_n.append(p)
            for multiple in range(p * p, n + 1, p):
                is_prime[multiple] = False

    product_of_primes = 1
    for p in primes_up_to_n:
        product_of_primes *= p

    # Smallest prime factor of the product is always 2 (since 2 is included)
    spf_product = 2

    # Print required outputs
    print(f"The smallest prime factor of the product of all primes up to {n} is: {spf_product}")
    print(f"The smallest prime factor of {n} is: {smallest_prime_factor(n)}")

    # Return the smallest prime factor of the original input n
    return smallest_prime_factor(n)
