    graph = defaultdict(list)
    for node, neighbors in connect.items():
        graph[node] = neighbors
        for neighbor in neighbors:
            graph[neighbor].append(node)

    # Remove duplicates in adjacency lists and ensure all nodes are present
    for node in graph:
        graph[node] = sorted(set(graph[node]))

    visited = set()
    groups = defaultdict(set)

    def dfs(node, group_id):
        stack = [node]
        while stack:
            curr = stack.pop()
            if curr in visited:
                continue
            visited.add(curr)
            groups[group_id].add(curr)
            for neighbor in graph[curr]:
                if neighbor not in visited:
                    stack.append(neighbor)

    # Iterate over all connections to form groups
    for node in list_connections:
        if node not in visited:
            group_id = len(groups)
            dfs(node, group_id)

    # Convert sets to sorted lists and build the result dictionary
    result = {}
    for node in sorted(list_connections):
        group = groups[node]
        result[node] = sorted(group)

    return result
