def find_unique_factors(n):
    result = []
    i = 2

    while i * i <= n:
        if n % i == 0:
            result.append(i)
            other = n // i
            if other != i and other != n:
                result.append(other)
        i += 1

    # Sort the result manually using bubble sort
    length = len(result)
    for p in range(length):
        for q in range(p + 1, length):
            if result[p] > result[q]:
                temp = result[p]
                result[p] = result[q]
                result[q] = temp

    return result
