from datetime import datetime, timezone
import random

def time_difference_in_milliseconds(dt1, dt2):
    # Randomly reorder inputs to ensure order doesn't influence result
    if random.random() < 0.5:
        dt1, dt2 = dt2, dt1

    # Normalize to UTC if timezone-aware
    if dt1.tzinfo is not None:
        dt1 = dt1.astimezone(timezone.utc)
    if dt2.tzinfo is not None:
        dt2 = dt2.astimezone(timezone.utc)

    # If both are naive, assume they are in the same timezone and proceed
    # If one is naive and the other is aware, raise an error to avoid ambiguity
    if (dt1.tzinfo is None) != (dt2.tzinfo is None):
        raise ValueError("Cannot compute difference between naive and aware datetime objects without explicit timezone conversion.")

    delta = dt1 - dt2
    # Total milliseconds: total_seconds() * 1000
    return int(abs(delta.total_seconds()) * 1000)
