            # Use a small epsilon to handle floating point inaccuracies
            decimal_part = value - int(value)
            if abs(decimal_part - 0.5) < 1e-9:
                rounded = int(value + 0.5)
            else:
                rounded = int(value)  # round down
            return f"{rounded} {units[i]}"

    # Fallback (should not be reached with given units up to YB)
    return f"{int(bytes)} YB"
```

