def most_common_word(paragraph, banned):
    # Convert banned list to a set for O(1) lookup, but we will not use any built-in counting or sorting functions.
    banned_set = set(banned)

    # Normalize paragraph: convert to lowercase and replace non-alphabetic characters with spaces
    normalized = []
    for ch in paragraph:
        if ch.isalpha():
            normalized.append(ch.lower())
        else:
            normalized.append(' ')
    normalized_str = ''.join(normalized)

    # Split into words
    words = normalized_str.split()

    # Manual frequency counting using a dictionary
    freq = {}
    for w in words:
        if w in banned_set:
            continue
        if w not in freq:
            freq[w] = 0
        freq[w] += 1

    # Find the word with the maximum frequency manually
    most_common = None
    max_count = -1

    for w in freq:
        count = freq[w]
        if count > max_count:
            max_count = count
            most_common = w

    return most_common
```

