def validate_input(s):
    # Check for empty string
    if len(s) == 0:
        return False

    # Check for leading whitespace
    if s[0] == ' ':
        return False

    # Check for trailing whitespace
    if s[-1] == ' ':
        return False

    # Check if the string contains any whitespace characters (other than leading/trailing which are already checked)
    for char in s:
        if char == ' ':
            return False

    # Check if the string is valid integer format
    # Valid formats: optional '+' or '-', followed by one or more digits
    if len(s) == 0:
        return False

    # Check for optional sign
    if s[0] == '+' or s[0] == '-':
        if len(s) == 1:
            return False
        # Rest must be digits
        for i in range(1, len(s)):
            if not ('0' <= s[i] <= '9'):
                return False
        return True
    else:
        # No sign, all characters must be digits
        for char in s:
            if not ('0' <= char <= '9'):
                return False
        return True
