def is_palindrome(s):
    # Helper: check if a character is alphanumeric without built-ins
    def is_alnum(ch):
        # Check if digit
        if '0' <= ch <= '9':
            return True
        # Check if uppercase letter
        if 'A' <= ch <= 'Z':
            return True
        # Check if lowercase letter
        if 'a' <= ch <= 'z':
            return True
        return False

    # Helper: convert uppercase to lowercase without built-ins
    def to_lower(ch):
        if 'A' <= ch <= 'Z':
            # 'A' is 65, 'a' is 97; difference is 32
            return chr(ord(ch) + 32)
        return ch

    # Two-pointer approach
    left, right = 0, len(s) - 1

    while left < right:
        # Move left pointer to next alphanumeric
        while left < right and not is_alnum(s[left]):
            left += 1
        # Move right pointer to previous alphanumeric
        while left < right and not is_alnum(s[right]):
            right -= 1

        if left >= right:
            break

        # Normalize both characters to lowercase
        l_char = to_lower(s[left])
        r_char = to_lower(s[right])

        if l_char != r_char:
            return False

        left += 1
        right -= 1

    return True
```

