def extract_unique_values(data):
    """
    Extracts all unique values from a JSON-like object, including nested structures.
    Returns a set of unique values (strings, integers, etc.).
    """
    unique_values = set()

    def traverse(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                traverse(value)
        elif isinstance(obj, list):
            for item in obj:
                traverse(item)
        else:
            # Add primitive values to the set
            unique_values.add(obj)

    traverse(data)
    return unique_values
