        # Given format key:type:value, we can split into 3 parts assuming value does not contain ':'.
        parts = item.split(':')
        if len(parts) != 3:
            raise ValueError(f"Invalid format: {item}")

        key, type_char, value_str = parts

        if type_char == 'i':
            # Convert to integer without using int()
            # Remove any leading/trailing whitespace
            value_str = value_str.strip()
            # Handle negative sign
            is_negative = value_str.startswith('-')
            if is_negative:
