            # Manual digit to integer conversion
            total = 0
            for ch in value_str:
                if not ch.isdigit():
                    raise ValueError(f"Invalid integer: {value_str}")
                total = total * 10 + (ord(ch) - ord('0'))

            if is_negative:
                total = -total
            result[key] = total

        elif type_char == 'f':
            # Convert to float without using float()
            value_str = value_str.strip()
            is_negative = value_str.startswith('-')
            if is_negative:
                value_str = value_str[1:]

            # Check for decimal point
            if '.' not in value_str:
                # It's an integer part only, treat as float
                int_part = value_str
                decimal_part = "0"
            else:
                int_part, decimal_part = value_str.split('.')

            # Convert integer part
