def build_graph(connections):
    edge_map = {}

    for node, neighbors in connections:
        for connected_node, label in neighbors:
            # Ensure consistent ordering: smaller node first
            if node < connected_node:
                u, v = node, connected_node
            else:
                u, v = connected_node, node

            if label not in edge_map:
                edge_map[label] = []
            # Avoid duplicates by checking if the edge already exists
            edge_exists = False
            for existing in edge_map[label]:
                if existing == (u, v):
                    edge_exists = True
                    break
            if not edge_exists:
                edge_map[label].append((u, v))

    return edge_map
