def is_palindrome(s):
    def is_alnum_char(c):
        # Check if character is alphanumeric without using built-in isalnum
        # Alphanumeric: A-Z, a-z, 0-9
        if 'A' <= c <= 'Z':
            return True
        if 'a' <= c <= 'z':
            return True
        if '0' <= c <= '9':
            return True
        return False

    def to_lower(c):
        # Convert uppercase to lowercase manually
        if 'A' <= c <= 'Z':
            return chr(ord(c) + 32)
        return c

    def helper(left, right):
        # Base case: pointers have crossed or met
        if left >= right:
            return True

        # Move left pointer to next alphanumeric character
        while left < right and not is_alnum_char(s[left]):
            left += 1

        # Move right pointer to previous alphanumeric character
        while left < right and not is_alnum_char(s[right]):
            right -= 1

        # If pointers crossed during skipping, we're done
        if left >= right:
            return True

        # Compare characters (case-insensitive)
        left_char = to_lower(s[left])
        right_char = to_lower(s[right])

        if left_char != right_char:
            return False

        # Recursive step
        return helper(left + 1, right - 1)

    return helper(0, len(s) - 1)
