def find_common_elements_with_counts(arrays):
    if not arrays:
        return {}

    # Start with the first array's elements as potential common elements
    common_elements = set(arrays[0])

    # Intersect with each subsequent array
    for arr in arrays[1:]:
        common_elements &= set(arr)

    # If no common elements, return empty dict
    if not common_elements:
        return {}

    # Count occurrences across all arrays
    count_dict = {}
    for num in common_elements:
        count = 0
        for arr in arrays:
            if num in arr:
                count += 1
        count_dict[num] = count

