def is_prime(n, known_primes=[2, 3, 5, 7, 11, 13, 17, 19]):
    if n < 2:
        return False
    if n == 2:
        return True
    if n % 2 == 0:
        return False

    # Extend known_primes only if needed up to sqrt(n)
    limit = int(n ** 0.5)
    while known_primes[-1] < limit:
        candidate = known_primes[-1] + 2
        while True:
            is_candidate_prime = True
            for p in known_primes:
                if p * p > candidate:
                    break
                if candidate % p == 0:
                    is_candidate_prime = False
                    break
            if is_candidate_prime:
                known_primes.append(candidate)
                break
            candidate += 2

    # Check divisibility by known primes up to sqrt(n)
    for p in known_primes:
        if p * p > n:
            break
        if n % p == 0:
            return False

    return True
