def unique_automaton(x, y, elem, neighbors, energy):
    # Dead cell (0)
    if elem == 0:
        if neighbors == 2 and energy >= 3:
            return (3, 5)
        else:
            return (0, energy)  # remains Dead, energy unchanged

    # Alive cell (3)
    if elem == 3:
        if 3 <= neighbors <= 5 and energy >= 2:
            return (3, energy)  # remains Alive, energy unchanged
        else:
            return (2, energy)  # becomes Decaying (state 2), energy unchanged

    # Decaying cells (1 or 2)
    if elem in (1, 2):
        new_state = elem - 1
        new_energy = energy - 1 if energy > 0 else 0
        return (new_state, new_energy)

    # Fallback (should not be reached with valid input)
    return (elem, energy)
