def length_of_lis(nums):
    if not nums:
        return 0

    tails = []  # tails[i] is the smallest tail of all increasing subsequences of length i+1

    for num in nums:
        # Use binary search to find the insertion point
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < num:
                left = mid + 1
            else:
                right = mid
        # If num is larger than all tails, append it
        if left == len(tails):
            tails.append(num)
        else:
            # Otherwise, replace the existing tail to maintain smallest possible tail
            tails[left] = num

    return len(tails)
```

