def isRepeatingPattern(s: str) -> (bool, str):
    n = len(s)
    if n == 0:
        return (False, None)

    # Try all possible lengths for the repeating substring t
    # The length of t must be a divisor of n and at least 1
    for length in range(1, n // 2 + 1):
        if n % length == 0:
            t = s[:length]
            # Check if repeating t constructs s
            if t * (n // length) == s:
                return (True, t)

    return (False, None)
