```python
def string_to_int_recursive(s, base=10):
    def char_to_value(ch):
        if ch.isdigit():
            return int(ch)
        else:
            # Handle uppercase and lowercase letters
            return ord(ch.upper()) - ord('A') + 10

    def helper(index, sign):
        if index == len(s):
            return 0
        current_char = s[index]
        if current_char == '-':
            return helper(index + 1, -1)
        elif current_char == '+':
            return helper(index + 1, 1)

        value = char_to_value(current_char)
        # Recursively process the rest and multiply current value by base
        return value * (base ** (len(s) - index - 1)) + helper(index + 1, 1)

    # Determine sign and strip it for processing
    sign = 1
    start_index = 0
    if s[0] == '-':
        sign = -1
        start_index = 1
    elif s[0] == '+':
        start_index = 1

    # Compute the integer value
    result = helper(start_index, 1)
    return sign * result
```

