def normalize_data(data):
    def flatten_dict(d, parent_key='', sep='_'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(flatten_dict(v, new_key, sep))
            else:
                items[new_key] = v
        return items

    # Check for tuple format: (dict, int)
    if isinstance(data, tuple) and len(data) == 2:
        inner_dict, count = data
        if isinstance(inner_dict, dict) and isinstance(count, int):
            flattened = flatten_dict(inner_dict)
            return (flattened, count)
        else:
            return (data, 0)

    # Check for single dict format
    if isinstance(data, dict):
        flattened = flatten_dict(data)
        return (flattened, 1)

    # Invalid input
    return (data, 0)
