def findClosestRoot(n, k):
    if n < 0:
        raise ValueError("n must be non-negative")
    if k < 1:
        raise ValueError("k must be at least 1")

    if n == 0:
        return 0
    if k == 1:
        return n

    low, high = 1, n
    while low <= high:
        mid = (low + high) // 2
        # Compute mid**k safely with early overflow check
        try:
            val = mid ** k
        except OverflowError:
            # Treat as too large
            val = n + 1

        if val <= n:
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    return ans
