```python
def has_cycle(graph):
    """
    Determines if a directed graph contains a cycle using DFS with three states:
    0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited.

    :param graph: dict where keys are nodes and values are lists of neighbor nodes
    :return: True if a cycle exists, False otherwise
    """
    # Ensure all nodes are considered, even if they have no outgoing edges
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    state = {node: 0 for node in all_nodes}  # 0: unvisited, 1: visiting, 2: visited

    def dfs(node):
        if state[node] == 1:
            return True  # Back edge found -> cycle
        if state[node] == 2:
            return False  # Already fully processed

        state[node] = 1  # Mark as visiting

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        state[node] = 2  # Mark as visited
        return False

    for node in all_nodes:
        if state[node] == 0:
            if dfs(node):
                return True

    return False
