def can_find_target_with_turns(matrix, target):
    if not matrix or not matrix[0]:
        return False

    rows, cols = len(matrix), len(matrix[0])
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]  # right, down, left, up

    def dfs(r, c, turns_left, direction_idx):
        if matrix[r][c] == target:
            return True

        if turns_left == 0:
            return False

        for new_dir_idx in range(4):
            if new_dir_idx == direction_idx:
                continue

            dr, dc = directions[new_dir_idx]
            nr, nc = r + dr, c + dc

            if 0 <= nr < rows and 0 <= nc < cols:
                if dfs(nr, nc, turns_left - 1, new_dir_idx):
                    return True

        return False

    # Start from top-left with no previous direction (so first move doesn't count as a turn)
    # We simulate starting with a "virtual" direction that matches any real direction to avoid counting the first move as a turn.
    # Instead, we handle the first move specially: we allow changing direction on the first step without consuming a turn.
    # Approach: try all 4 initial directions from (0,0) with 3 turns allowed.
    for start_dir in range(4):
        dr, dc = directions[start_dir]
        nr, nc = 0 + dr, 0 + dc
        if 0 <= nr < rows and 0 <= nc < cols:
            if dfs(nr, nc, 3, start_dir):
                return True

    return False
```

