def count_event_repetitions(event_names):
    from collections import defaultdict
    import re

    counts = defaultdict(int)

    for event in event_names:
        # Extract the base event name by removing optional "[N]" at the end
        match = re.search(r'\s*\[\d+\]\s*$', event)
        if match:
            base_name = event[:match.start()].strip()
        else:
            base_name = event.strip()

        counts[base_name] += 1

    # Filter out events that were held only once
    return {k: v for k, v in counts.items() if v > 1}
