def max_gcd_after_removal(numbers):
    n = len(numbers)
    if n < 2:
        return 0

    # Precompute prefix and suffix GCDs without using built-in gcd
    def compute_gcd(a, b):
        while b:
            a, b = b, a % b
        return a

    prefix_gcd = [0] * n
    suffix_gcd = [0] * n

    prefix_gcd[0] = numbers[0]
    for i in range(1, n):
        prefix_gcd[i] = compute_gcd(prefix_gcd[i - 1], numbers[i])

    suffix_gcd[n - 1] = numbers[n - 1]
    for i in range(n - 2, -1, -1):
        suffix_gcd[i] = compute_gcd(suffix_gcd[i + 1], numbers[i])

    max_g = 0

    # Remove element at index i
    for i in range(n):
        if i == 0:
            g = compute_gcd(suffix_gcd[1], suffix_gcd[2] if n > 2 else 0)
            if n == 2:
                g = suffix_gcd[1]
        elif i == n - 1:
            g = compute_gcd(prefix_gcd[n - 2], prefix_gcd[n - 3] if n > 2 else 0)
            if n == 2:
                g = prefix_gcd[0]
        else:
            g = compute_gcd(prefix_gcd[i - 1], suffix_gcd[i + 1])

        if g > max_g:
            max_g = g

    return max_g
```

