def get_prime_factors(n):
    if n <= 1:
        return []

    factors = []
    d = 2

    # Handle factor 2 separately
    if n % d == 0:
        factors.append(d)
        while n % d == 0:
            n //= d

    d = 3
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 2

    if n > 1:
        factors.append(n)

    return factors
