def alternate_concat(str1: str, str2: str, k: int = 1) -> str:
    if k <= 0:
        k = 1

    def split_into_chunks(s: str, chunk_size: int) -> list[str]:
        chunks = []
        for i in range(0, len(s), chunk_size):
            chunks.append(s[i:i + chunk_size])
        return chunks

    chunks1 = split_into_chunks(str1, k)
    chunks2 = split_into_chunks(str2, k)

    result = []

    # Alternate until both lists are exhausted
    max_len = max(len(chunks1), len(chunks2))
    for i in range(max_len):
        if i < len(chunks1):
            result.append(chunks1[i])
        if i < len(chunks2):
            result.append(chunks2[i])

    return "".join(result)
