def extract_product_code_from_string(input_string):
    import re

    # Pattern explanation:
    # - Look for "product_code=" (allowing optional spaces around '=' as per examples)
    # - Then capture the value which may be enclosed in single or double quotes
    # - The value itself consists of alphanumeric characters, hyphens, and underscores
    # - We use a non-greedy match to stop at the closing quote or end of string

    pattern = r'product_code\s*=\s*(?:["\'])([A-Za-z0-9_-]+)\1'

    match = re.search(pattern, input_string)
    if match:
        return match.group(1)
    else:
        # Also handle case without quotes if the value is directly alphanumeric/hyphen/underscore
        pattern_unquoted = r'product_code\s*=\s*([A-Za-z0-9_-]+)'
        match_unquoted = re.search(pattern_unquoted, input_string)
        if match_unquoted:
            return match_unquoted.group(1)
        return None
