def is_perfect_square(n):
    if n < 0:
        return False
    if n == 0 or n == 1:
        return True

    low, high = 1, n // 2
    while low <= high:
        mid = (low + high) // 2
        sq = mid * mid
        if sq == n:
            return True
        elif sq < n:
            low = mid + 1
        else:
            high = mid - 1

    return False
