def largest_prime_factor(n: int) -> int:
    if n <= 1:
        return n  # No prime factors for 1 or less; return as-is per spec constraints

    # Remove factors of 2
    while n % 2 == 0:
        n //= 2

    # Check odd factors up to sqrt(n)
    factor = 3
    while factor * factor <= n:
        while n % factor == 0:
            n //= factor
        factor += 2

    # If n is now greater than 1, it is a prime
    if n > 1:
        return n

    # If we reduced n completely, the last factor removed is the largest
    # We need to track the largest factor found during division
    # Re-run to capture the largest factor properly
    temp = n
    largest = 2
    while temp % 2 == 0:
        temp //= 2
        largest = 2

    factor = 3
    while factor * factor <= temp:
        while temp % factor == 0:
            temp //= factor
            largest = factor
        factor += 2

    if temp > 1:
        largest = temp

    return largest
