def generate_primes(count):
    if count <= 0:
        return []
    if count == 1:
        return [2]

    # Estimate upper bound using the prime number theorem approximation
    # n-th prime is approximately n * (ln n + ln ln n) for n >= 6
    if count < 6:
        upper_bound = 15
    else:
        import math
        upper_bound = int(count * (math.log(count) + math.log(math.log(count)))) + 10

    sieve = [True] * (upper_bound + 1)
    sieve[0] = sieve[1] = False

    for i in range(2, int(upper_bound ** 0.5) + 1):
        if sieve[i]:
            for j in range(i * i, upper_bound + 1, i):
                sieve[j] = False

    primes = [i for i, is_prime in enumerate(sieve) if is_prime]
    return primes[:count]
