        "lazy": ["sluggish", "idle"],
        "dog": ["canine", "hound"],
        "jumps": ["leaps", "springs"],
        "over": ["above", "across"],
        "lazy": ["sluggish", "idle"],
    }

    def get_synonym_set(word):
        return set(synonyms.get(word, [word]))

    # Build a mapping from each word in target_phrase to its synonym set
    target_syn_sets = [get_synonym_set(word) for word in target_phrase]

    n_source = len(source_text)
    n_target = len(target_phrase)

    start_indices = []
    end_indices = []
    matched_words = []

    for i in range(n_source - n_target + 1):
        match = True
        current_words = []
        for j in range(n_target):
            source_word = source_text[i + j]
            if source_word not in target_syn_sets[j]:
                match = False
                break
            current_words.append(source_word)
        if match:
            start_indices.append(i)
            end_indices.append(i + n_target - 1)
            matched_words.append(current_words)

    if not start_indices:
        return (False, [], [], [])

    return (True, start_indices, end_indices, matched_words)
