def merge_configurations(base_config, *additional_dicts, **kwargs):
    def _deep_merge(target, source):
        """Recursively merge source into target and return a new merged dict."""
        result = dict(target)  # shallow copy of target
        for key, value in source.items():
            if key in result and isinstance(result[key], dict) and isinstance(value, dict):
                result[key] = _deep_merge(result[key], value)
            else:
                result[key] = value
        return result

    # Start with a copy of the base configuration
    merged = dict(base_config)

    # Merge additional dictionaries in order
    for adict in additional_dicts:
        if not isinstance(adict, dict):
            raise TypeError("Additional configurations must be dictionaries.")
        merged = _deep_merge(merged, adict)

    # Merge keyword arguments (they act as a final dictionary)
    merged = _deep_merge(merged, kwargs)

    return merged
