def encode_message(message: str, encoding: str) -> bytes:
    try:
        return message.encode(encoding)
    except LookupError:
        # Invalid encoding: apply Caesar cipher shift of 3
        result = []
        for ch in message:
            if 'A' <= ch <= 'Z':
                shifted = chr((ord(ch) - ord('A') + 3) % 26 + ord('A'))
                result.append(shifted)
            elif 'a' <= ch <= 'z':
