```python
def max_depth(d, seen=None):
    if seen is None:
        seen = set()

    # Check for self-referencing loops by tracking object identity
    if id(d) in seen:
        return 0

    # Mark current dictionary as seen to prevent infinite recursion in case of cycles
    seen.add(id(d))

    # If the dictionary is empty or contains no nested dictionaries, it's a leaf
    if not d or not any(isinstance(v, dict) for v in d.values()):
        return 1

    # Calculate the maximum depth among all nested dictionaries
    max_d = 0
    for value in d.values():
        if isinstance(value, dict):
            max_d = max(max_d, max_depth(value, seen))

    # Depth is 1 (for the current level) + maximum depth of children
    return 1 + max_d
