def fibonacci_memoization(n, memo=None):
    if memo is None:
        memo = {}

    if n < 0:
        raise ValueError("n must be non-negative")
    if n == 0:
        return [0]
    if n == 1:
        return [0, 1]

    # Ensure base cases are in memo
    if 0 not in memo:
        memo[0] = 0
    if 1 not in memo:
        memo[1] = 1

    result = [0, 1]

    for i in range(2, n + 1):
        if i not in memo:
            memo[i] = memo[i - 1] + memo[i - 2]
        result.append(memo[i])

    return result
