def parse_expression(expression: str) -> list:
    import re

    # Remove all spaces to simplify parsing
    expression = expression.replace(" ", "")

    # Validate allowed characters
    if not re.fullmatch(r'\[.*\]', expression):
        raise ValueError("Invalid expression: must be a list representation.")
    if not re.fullmatch(r'[\[\],0-9]+', expression):
        raise ValueError("Invalid expression: contains disallowed characters.")

    # Helper to parse a list from the current position
    def parse_list(s: str, pos: list) -> tuple:
        # pos is a list to allow mutable update of current index
        start = pos[0]
        if s[start] != '[':
            raise ValueError(f"Expected '[' at position {start}")
        pos[0] += 1  # skip '['

        result = []
        while pos[0] < len(s):
            if s[pos[0]] == ']':
                pos[0] += 1  # skip ']'
                return result, pos[0]

            # Parse integer
            if s[pos[0]].isdigit():
                num_start = pos[0]
                while pos[0] < len(s) and s[pos[0]].isdigit():
                    pos[0] += 1
                num = int(s[num_start:pos[0]])
                result.append(num)
            # Parse nested list
            elif s[pos[0]] == '[':
                sub_list, pos[0] = parse_list(s, pos)
                result.append(sub_list)
            else:
                raise ValueError(f"Unexpected character '{s[pos[0]]}' at position {pos[0]}")

            # Skip comma if present
            if pos[0] < len(s) and s[pos[0]] == ',':
                pos[0] += 1

        if pos[0] >= len(s) or s[pos[0]] != ']':
            raise ValueError("Missing closing bracket ']'.")

        return result, pos[0]

    if not expression:
        raise ValueError("Empty input string.")

    pos = [0]
    parsed_list, end_pos = parse_list(expression, pos)

    if end_pos != len(expression):
        raise ValueError("Extra characters after the list.")

    return parsed_list

