def rotate_matrix_90_clockwise(matrix):
    m = len(matrix)
    n = len(matrix[0]) if m > 0 else 0

    if m == n:
        # In-place rotation for square matrix
        # Transpose
        for i in range(m):
            for j in range(i + 1, m):
                matrix[i][j], matrix[j][i] = matrix[j][i], matrix[i][j]
        # Reverse each row
        for i in range(m):
            matrix[i].reverse()
        return matrix
    else:
        # Create new matrix for non-square case
        rotated = [[0] * m for _ in range(n)]
        for i in range(m):
            for j in range(n):
                rotated[j][m - 1 - i] = matrix[i][j]
        return rotated
