def calculate_tree_height(tree, root=None, prev_prime=False):
    if not tree:
        return 0

    if root is None:
        root = next(iter(tree))

    def is_prime_name(name):
        # Sum of ASCII values of characters in the name
        ascii_sum = sum(ord(c) for c in name)
        if ascii_sum < 2:
            return False
        for i in range(2, int(ascii_sum ** 0.5) + 1):
            if ascii_sum % i == 0:
                return False
        return True

    def dfs(node, current_height, prev_prime):
        # If current node name is prime and previous was prime, this path is invalid
        if is_prime_name(node) and prev_prime:
            return 0  # This path is invalid, so it contributes no height

        current_height += 1

        children = tree.get(node, [])
        if not children:
            return current_height

        max_height = 0
        for child in children:
            # Determine if current node is prime for the next recursion
            current_is_prime = is_prime_name(node)
            child_height = dfs(child, current_height, current_is_prime)
            if child_height > max_height:
                max_height = child_height

        return max_height

    # Start DFS from root; root's "previous prime" status is False initially
    return dfs(root, 0, False)
