def transpose(matrix):
    if not matrix:
        return []

    rows = len(matrix)
    cols = len(matrix[0])

    # Initialize transposed matrix with None
    transposed = [[None for _ in range(rows)] for _ in range(cols)]

    for r in range(rows):
        for c in range(cols):
            transposed[c][r] = matrix[r][c]

    return transposed
