def count_balanced_brackets(s):
    stack = []  # stores indices of '['
    non_nested = 0
    nested = 0
    n = len(s)

    for i, ch in enumerate(s):
        if ch == '[':
            stack.append(i)
        elif ch == ']':
            if not stack:
                return -1  # unmatched closing bracket
            open_idx = stack.pop()
            # Check if there is any bracket between open_idx and i
            has_inner = False
            for k in range(open_idx + 1, i):
                if s[k] in '[]':
                    has_inner = True
                    break
            if has_inner:
                nested += 1
            else:
                non_nested += 1

    if stack:
        return -1  # unmatched opening bracket

    return [non_nested, nested]
