import re
from collections import defaultdict

def match_filenames(filenames, patterns):
    # Group patterns by their starting character
    pattern_groups = defaultdict(list)
    for p in patterns:
        if p:  # ignore empty patterns
            first_char = p[0]
            pattern_groups[first_char].append(p)

    result = {}

    for filename in filenames:
        matched = False
        first_char = filename[0] if filename else ''
        # Only check patterns that start with the same character
        if first_char in pattern_groups:
            for pattern in pattern_groups[first_char]:
                try:
                    if re.fullmatch(pattern, filename):
                        matched = True
                        break
                except re.error:
                    # If a pattern is invalid, skip it
                    continue
        result[filename] = matched

    return result
