def find_smallest_missing_positive(nums):
    n = len(nums)
    # Create a boolean array to mark presence of positive integers in range [1, n+1]
    present = [False] * (n + 2)

    for num in nums:
        if 1 <= num <= n + 1:
            present[num] = True

    for i in range(1, n + 2):
        if not present[i]:
            return i

    return n + 1
